import { z } from 'zod';

const OrderBody = z.object({
  sku: z.string().min(1),
  quantity: z.number().int().positive().max(100),
});
type OrderBody = z.infer<typeof OrderBody>;

export async function createOrder(req: Request): Promise<Response> {
  const parsed = OrderBody.safeParse(await req.json());
  if (!parsed.success) {
    return Response.json({ errors: parsed.error.flatten().fieldErrors }, { status: 400 });
  }
  const order = await placeOrder(parsed.data);
  return Response.json(order, { status: 201 });
}
